import{_ as o,r as n,o as p,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Section - October CMS - 4.x","titleTemplate":false,"description":"Define a website section with a dedicated URL.","frontmatter":{"subtitle":"Define a website section with a dedicated URL."},"headers":[{"level":2,"title":"Available Properties","slug":"available-properties","link":"#available-properties","children":[]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"Changing the Lookup Identifier","slug":"changing-the-lookup-identifier","link":"#changing-the-lookup-identifier","children":[]},{"level":2,"title":"How the Component Variable Works","slug":"how-the-component-variable-works","link":"#how-the-component-variable-works","children":[]},{"level":2,"title":"Checking Record Existence","slug":"checking-record-existence","link":"#checking-record-existence","children":[]},{"level":2,"title":"Accessing the Entry Type","slug":"accessing-the-entry-type","link":"#accessing-the-entry-type","children":[]},{"level":2,"title":"Using the Full Slug","slug":"using-the-full-slug","link":"#using-the-full-slug","children":[]}],"relativePath":"4.x/cms/components/section.md","filePath":"4.x/cms/components/section.md"}'),u={name:"4.x/cms/components/section.md"};function r(d,a,g,k,h,m){const e=n("pre-heading"),t=n("post-heading");return p(),l("div",null,[s(e),a[0]||(a[0]=c("h1",null,"Section",-1)),s(t),a[1]||(a[1]=i(`<p>The <code>section</code> component defines a website section with a supporting entry. This section will be used when previewing the entry from the backend panel.</p><h2 id="available-properties"><a href="#available-properties" class="header-anchor">#</a> Available Properties</h2><p>The following properties are supported by the component.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>The handle of the <a href="./../tailor/blueprints.html">entry blueprint</a>.</td></tr><tr><td><strong>identifier</strong></td><td>Use this identifier key to look up the entry, supported values are <code>slug</code>, <code>fullslug</code> or <code>id</code>. Default: <code>slug</code></td></tr><tr><td><strong>value</strong></td><td>Use this identifier value to use to look up the entry, optional. Leave empty to use the identifier key as the URL parameter name. Can be set to a hard coded value, or a custom parameter, eg: <code>{{ :slug }}</code></td></tr><tr><td><strong>isDefault</strong></td><td>Make this the default page when previewing the entry. Default: <code>true</code>.</td></tr></tbody></table></div><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>The following creates a section for the <strong>Blog\\Author</strong> entry and locates it using the default <code>:slug</code> <a href="./../themes/pages.html">URL parameter</a>. The author name is displayed as a title by accessing the <code>{{ section.title }}</code> Twig variable.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> section<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>When multiple sections are used on the same page, the component alias can be used to assign a different the variable name available to the page. The following component alias <strong>author</strong> makes the title available using the <code>{{ author.title }}</code> Twig variable instead.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section author</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> author<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="changing-the-lookup-identifier"><a href="#changing-the-lookup-identifier" class="header-anchor">#</a> Changing the Lookup Identifier</h2><p>The default identifier is <code>slug</code> and this can be changed by changing the <code>identifier</code> property, for example, locating a record using the <code>id</code> column instead. Notice that the page URL also changes to use an <code>:id</code> parameter name.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><p>You may hard code the identifier lookup using the <code>value</code> property, for example, setting it to <strong>7</strong> will show the record with a static lookup.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/ceo</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">7</span>
</code></pre></div><p>The <code>value</code> property also accepts external parameters, the following uses the <strong>foobar</strong> URL parameter to look up the record.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:foobar</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :foobar }}</span>&quot;</span>
</code></pre></div><div class="custom-block warning"><p>Previewing links and using the <a href="./../../element/form/widget-pagefinder.html">Page Finder widget</a> do not support identifiers with custom values.</p></div><h2 id="how-the-component-variable-works"><a href="#how-the-component-variable-works" class="header-anchor">#</a> How the Component Variable Works</h2><p>The component variable (e.g. <code>section</code> or your alias like <code>author</code>) acts as a smart proxy. Accessing an attribute returns the record field value directly.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> author<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> author<span class="token punctuation">.</span>slug <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Calling a method starts a new <a href="./../../extend/database/query.html">database model query</a> instead. For example, the following creates a new query to fetch related posts.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> recentPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>author_id<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> author<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block warning"><p>When accessing the component variable as an attribute (e.g. <code>author.title</code>) or as a query (e.g. <code>author.where(...)</code>) the result will be different. Attributes return a stored value from the primary record, whereas methods initiate a new database query.</p></div><h2 id="checking-record-existence"><a href="#checking-record-existence" class="header-anchor">#</a> Checking Record Existence</h2><p>In most cases you will want to display a 404 page when a record cannot be found. This is possible by using an <code>{% if %}</code> statement combined with the <code>abort(404)</code> function.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> author <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>The <a href="./../../markup/function/abort.html"><code>abort()</code> Twig function</a> is used to show a 404 page when the record is not found.</p></div><h2 id="accessing-the-entry-type"><a href="#accessing-the-entry-type" class="header-anchor">#</a> Accessing the Entry Type</h2><p>When using the <a href="./blueprints.html">Content Groups</a> feature of the entry blueprint, you may access the group code using the <code>content_group</code> attribute. For example, a post may have a content group of <strong>regular_post</strong> and <strong>markdown_post</strong> where the content is handled differently.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> post<span class="token punctuation">.</span>content_group <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>markdown_post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as Markdown --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>md <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as HTML --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="using-the-full-slug"><a href="#using-the-full-slug" class="header-anchor">#</a> Using the Full Slug</h2><p>If the entry type is a <code>structure</code>, then it will have a <strong>fullslug</strong> attribute available. To use the full slug in the page URL it should be defined as a <a href="./../themes/pages.html">wildcard URL parameter</a>. The <code>identifier</code> property of the component should be set to <strong>fullslug</strong>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">fullslug</span>&quot;</span>
</code></pre></div><p>As an alternative approach, we recommend targeting the <strong>id</strong> and placing it at the end of the URL instead. This allows the record to be moved around freely without breaking links in your website. The following example shows how to achieve this with a redirect for any previously used URLs.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> article <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> article<span class="token punctuation">.</span>fullslug <span class="token operator">!=</span> this<span class="token punctuation">.</span>param<span class="token punctuation">.</span>fullslug <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span>this<span class="token operator">|</span>page<span class="token punctuation">(</span><span class="token punctuation">{</span> fullslug<span class="token punctuation">:</span> article<span class="token punctuation">.</span>fullslug <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">301</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- Contents here --&gt;</span>
</code></pre></div></div><div class="custom-block tip"><p>The <a href="./../../markup/function/redirect.html"><code>redirect()</code> Twig function</a> is used for a permanent 301 redirect when the slug does not match. The <a href="./../../markup/filter/page.html"><code>|page</code> Twig filter</a> supplies the current page and rewrites the <code>fullslug</code> URL parameter to the correct match.</p></div>`,36))])}const f=o(u,[["render",r]]);export{w as __pageData,f as default};
